    front_text: 'What are PT considerations for patients on beta-blockers?',
    back_text: 'Beta-Blockers:\n\nIdentification: End in "-olol"\n(metoprolol, atenolol, propranolol)\n\nEffects:\n• Reduce heart rate\n• Reduce blood pressure\n• Blunt HR response to exercise\n\nPT Considerations:\n• CANNOT use HR to monitor intensity\n• Use RPE (Rate of Perceived Exertion) instead\n• Target RPE: 11-14 (moderate)\n• Watch for orthostatic hypotension\n• May cause fatigue, cold extremities',
    source_pdf_id: null,
