    back_text: 'Sensitivity vs Specificity:\n\nSENSITIVITY (SnNout):\n• Ability to detect DISEASE\n• True positive rate\n• High sensitivity = few false negatives\n• Negative result RULES OUT condition\n• "Sensitive tests catch the Sick"\n\nSPECIFICITY (SpPin):\n• Ability to detect NO disease\n• True negative rate\n• High specificity = few false positives\n• Positive result RULES IN condition\n• "Specific tests catch the healthy Surely"\n\nSnNout: Sensitive, Negative, rules OUT\nSpPin: Specific, Positive, rules IN',
