    back_text: 'ICU-ACQUIRED WEAKNESS (ICUAW):\n\nDEFINITION:\n- Generalized weakness developing during ICU stay\n- No other explanation for weakness\n- MRC sum score <48/60\n\nRISK FACTORS:\n- Prolonged mechanical ventilation\n- Sepsis, multi-organ failure\n- Hyperglycemia\n- Corticosteroid use\n- Neuromuscular blocking agents\n- Immobility\n\nCOMPONENTS:\n- Critical Illness Polyneuropathy (CIP)\n- Critical Illness Myopathy (CIM)\n- Often combined (CINM)\n\nPRESENTATION:\n- Symmetric weakness\n- Affects limbs and respiratory muscles\n- Difficulty weaning from ventilator\n- Reduced DTRs\n\nPT MANAGEMENT:\n- Early mobilization in ICU\n- Progressive mobility protocol\n- ROM, positioning\n- Strengthening as tolerated\n- May take months to recover\n\nPREVENTION: Early mobility is KEY!',
