    back_text: 'NEONATAL ABSTINENCE SYNDROME (NAS):\n\nDEFINITION:\n- Withdrawal syndrome in newborns\n- Prenatal opioid or other substance exposure\n- Onset: 24-72 hours after birth\n\nSYMPTOMS:\n- CNS: Tremors, seizures, high-pitched cry, irritability\n- GI: Poor feeding, vomiting, diarrhea\n- Autonomic: Fever, sweating, yawning, sneezing\n- Motor: Increased tone, hyperreflexia\n\nFINNEGAN SCORING:\n- Standardized assessment\n- Guides pharmacological treatment\n- Scored every 3-4 hours\n\nPT INTERVENTIONS:\n- Swaddling (promotes flexion)\n- Skin-to-skin contact\n- Dim, quiet environment\n- Slow, gentle handling\n- Non-nutritive sucking\n- Positioning for comfort\n- Minimize stimulation\n\nDEVELOPMENTAL CONCERNS:\n- Motor delays possible\n- Sensory processing issues\n- Long-term follow-up recommended\n\nFamily support essential!',
