    front_text: 'How do you assess and treat diastasis recti abdominis (DRA)?',
    back_text: 'DIASTASIS RECTI ABDOMINIS (DRA):\n\nDEFINITION:\n- Separation of rectus abdominis at linea alba\n- Common during/after pregnancy\n- >2 finger widths (>2 cm) considered significant\n\nASSESSMENT:\n- Supine, knees bent\n- Head lift (partial curl-up)\n- Palpate above/at/below umbilicus\n- Measure: Width (fingers/cm) and depth\n- Note tissue tension under fingers\n\nCLASSIFICATION:\n- Mild: 2-3 cm\n- Moderate: 3-5 cm\n- Severe: >5 cm\n\nTREATMENT:\n- Core activation (TA, pelvic floor)\n- Breath work with engagement\n- Avoid Valsalva maneuver\n- Avoid crunches, sit-ups initially\n- Progress to functional integration\n- Posture education\n- Splinting/support may help\n\nEXERCISES:\n- Diaphragmatic breathing\n- TA activation (drawing in)\n- Pelvic floor coordination\n- Progressive core strengthening\n\nConsider referral if not responding or severe',
