    back_text: 'DELIRIUM vs DEMENTIA:\n\nDELIRIUM:\n- Acute onset (hours to days)\n- Fluctuating course\n- Attention impaired (KEY feature)\n- Consciousness altered\n- Often reversible\n- Medical cause (infection, meds, metabolic)\n\nDEMENTIA:\n- Insidious onset (months to years)\n- Progressive, stable course\n- Attention preserved until late\n- Consciousness clear\n- Generally irreversible\n- Neurodegenerative cause\n\nCAM (Confusion Assessment Method):\n1. Acute onset, fluctuating course\n2. Inattention\n3. Disorganized thinking\n4. Altered consciousness\n(1 + 2 + either 3 or 4 = Delirium)\n\nDELIRIUM CAUSES (DELIRIUMS):\n- Drugs\n- Electrolytes\n- Lack of drugs (withdrawal)\n- Infection\n- Reduced sensory input\n- Intracranial\n- Urinary/fecal retention\n- Myocardial/pulmonary\n- Subdural\n\nPT IMPLICATIONS:\n- May need to defer therapy in acute delirium\n- Reorient patient\n- Simplify instructions\n- Prevent falls',
