    back_text: 'Levels of Evidence (Oxford):\n\nLEVEL I (Strongest):\n- Systematic reviews of RCTs\n- Meta-analyses\n- High-quality RCTs\n\nLEVEL II:\n- Lesser quality RCTs\n- Prospective cohort studies\n\nLEVEL III:\n- Case-control studies\n- Retrospective cohort studies\n\nLEVEL IV:\n- Case series\n- Poor quality cohort/case-control\n\nLEVEL V (Weakest):\n- Expert opinion\n- Case reports\n- Bench research\n\nRemember: Higher level = less bias, more generalizable\n\nMnemonic: "SR MCCC" (Systematic Review, Meta-analysis, RCT, Cohort, Case-control, Case series)',
