    front_text: 'What is internal validity vs external validity?',
    back_text: 'Internal vs External Validity:\n\nINTERNAL VALIDITY:\n- Can results be trusted within study?\n- Did intervention cause the outcome?\n- Threats: Selection bias, history, maturation, testing effects, attrition\n- Controlled by: Randomization, blinding, control groups\n\nEXTERNAL VALIDITY:\n- Can results be generalized?\n- Applicability to real-world population\n- Threats: Narrow inclusion criteria, artificial settings, volunteer bias\n- Improved by: Diverse sample, realistic settings\n\nTRADE-OFF:\n- High internal validity often = lower external validity\n- Tightly controlled studies may not reflect real practice\n\nRemember:\n- Internal = ACCURACY within study\n- External = APPLICABILITY outside study',
