    back_text: 'Types of Bias:\n\nSELECTION BIAS:\n- Non-random group assignment\n- Systematic differences at baseline\n- Prevented by: Randomization\n\nINFORMATION/MEASUREMENT BIAS:\n- Errors in measuring variables\n- Types: Recall bias, interviewer bias\n- Prevented by: Blinding, standardized measures\n\nCONFOUNDING:\n- Third variable affects both exposure and outcome\n- Prevented by: Randomization, stratification, multivariate analysis\n\nATTRITION BIAS:\n- Differential dropout between groups\n- Prevented by: Intention-to-treat analysis\n\nPUBLICATION BIAS:\n- Positive results more likely published\n- Addressed by: Funnel plots, trial registries\n\nHAWTHORNE EFFECT:\n- Behavior changes due to being observed\n- Prevented by: Blinding',
