    front_text: 'How do you calculate sensitivity and specificity?',
    back_text: 'Sensitivity & Specificity Calculations:\n\n              Disease+  Disease-\nTest+         TP        FP\nTest-         FN        TN\n\nSENSITIVITY = TP / (TP + FN)\n- True positive rate\n- "Of those WITH disease, how many test positive?"\n- SnNout: Sensitive Negative rules OUT\n\nSPECIFICITY = TN / (TN + FP)\n- True negative rate\n- "Of those WITHOUT disease, how many test negative?"\n- SpPin: Specific Positive rules IN\n\nEXAMPLE:\n- 100 patients with disease\n- 90 test positive (TP=90, FN=10)\n- Sensitivity = 90/100 = 90%\n\nCLINICAL APPLICATION:\n- High sensitivity: Good screening test\n- High specificity: Good confirmatory test',
    source_pdf_id: null,
    source_page_number: null,
