    back_text: 'Predictive Values:\n\nPOSITIVE PREDICTIVE VALUE (PPV):\n- PPV = TP / (TP + FP)\n- "If test is positive, what is probability of disease?"\n- Affected by disease prevalence\n- Higher prevalence = higher PPV\n\nNEGATIVE PREDICTIVE VALUE (NPV):\n- NPV = TN / (TN + FN)\n- "If test is negative, what is probability of NO disease?"\n- Higher prevalence = lower NPV\n\nDIFFERENCE FROM SENS/SPEC:\n- Sens/Spec: Fixed properties of test\n- PPV/NPV: Vary with prevalence\n\nCLINICAL EXAMPLE:\n- Rare disease: Positive test likely false positive (low PPV)\n- Common disease: Positive test likely true positive (high PPV)\n\nRemember: PPV/NPV answer "What does this test result mean for MY patient?"',
    source_pdf_id: null,
