    back_text: 'Likelihood Ratios:\n\nPOSITIVE LIKELIHOOD RATIO (LR+):\n- LR+ = Sensitivity / (1 - Specificity)\n- How much more likely positive test in disease vs no disease\n- LR+ > 10: Strong evidence to rule IN\n\nNEGATIVE LIKELIHOOD RATIO (LR-):\n- LR- = (1 - Sensitivity) / Specificity\n- How much less likely negative test in disease vs no disease\n- LR- < 0.1: Strong evidence to rule OUT\n\nINTERPRETATION:\n- LR = 1: Test provides no information\n- LR 2-5: Small shift in probability\n- LR 5-10: Moderate shift\n- LR > 10: Large shift\n\nADVANTAGE:\n- Not affected by prevalence\n- Can be used with pretest probability\n- More clinically useful than sens/spec alone\n\nPost-test odds = Pre-test odds x LR',
