    options: [
      { text: 'The results are clinically significant', is_correct: false },
      { text: 'The results are statistically significant', is_correct: true },
      { text: 'There is a 3% chance the treatment is effective', is_correct: false },
      { text: 'The effect size is 0.03', is_correct: false },
    ],
    explanation: 'A p-value of 0.03 is less than the alpha level of 0.05, indicating statistical significance. This means there is less than a 5% probability the results occurred by chance. Statistical significance does not equal clinical significance, which must be evaluated separately.',
