    question_text: 'During examination of a patient with knee pain, the therapist applies a valgus stress to the knee at 30 degrees flexion. There is excessive medial joint opening. The same test at full extension shows no laxity. What does this finding indicate?',
    options: [
      { text: 'Isolated MCL injury', is_correct: true },
      { text: 'Combined MCL and ACL injury', is_correct: false },
      { text: 'Combined MCL and PCL injury', is_correct: false },
      { text: 'LCL injury', is_correct: false },
    ],
    explanation: 'Valgus stress testing at 30 degrees flexion isolates the MCL. If laxity is present at 30 degrees but NOT at full extension, this indicates an isolated MCL injury. Laxity at both positions would suggest combined MCL and cruciate ligament injury, as the cruciates provide secondary restraint at full extension.',
