    explanation: 'This describes the Empty Can (Jobe) test, which specifically assesses the supraspinatus muscle. The thumb-down position internally rotates the shoulder, isolating the supraspinatus while minimizing deltoid contribution. Weakness and pain suggest supraspinatus pathology.',
